% ==========================================================
% Simulation of Basic Communication System (Tx-Channel-Rx)
% ==========================================================
clc;
clear;
close all;

% 1. Transmitter (Tx) Parameters
fs = 1000;                      % Sampling frequency (Hz)
t = 0:(1/fs):(1 - 1/fs);        % Time vector (1 second)
f_carrier = 5;                  % Message frequency (5 Hz)
A = 1.0;                        % Amplitude (1 V)
tx_signal = A * sin(2 * pi * f_carrier * t);

% 2. Noise levels to evaluate (standard deviation sigma)
sigma_values = [0.0, 0.1, 0.5, 2.0, 5.0];
labels = {'Clean (No Noise)', 'Slightly Noisy', 'Visible Distortion', ...
          'Very Noisy (Masked)', 'Almost Lost (Pure Noise)'};

figure('Color', 'w', 'Position', [100, 80, 900, 750]);

for i = 1:length(sigma_values)
    sigma = sigma_values(i);

    % 3. Wireless Channel (AWGN)
    noise = sigma * randn(size(t));
    rx_signal = tx_signal + noise;

    % 4. Receiver (Rx) Display Subplot
    subplot(length(sigma_values), 1, i);
    plot(t, rx_signal, 'b-', 'LineWidth', 1.2); hold on;
    if sigma > 0
        plot(t, tx_signal, 'k--', 'LineWidth', 0.8);
    end
    hold off;
    grid on;

    title(sprintf('Noise \sigma = %.1f : %s', sigma, labels{i}), ...
          'FontWeight', 'bold', 'FontSize', 10);
    xlabel('Time (s)');
    ylabel('Amplitude (V)');
    ylim([-7, 7]);
end

sgtitle('Simulation of Basic Communication System (Tx - Channel - Rx)');

fprintf('Simulation completed successfully across %d noise levels.\n', length(sigma_values));

clc;
clear;
close all;

% ==========================================================
% Frequency Reuse Demonstration in Cellular Systems
% ==========================================================

R = 1;              % Normalized cell radius
N = 7;              % Cluster size

% Frequency groups
freq = 1:N;

% Hexagonal cell geometry (pointy-top regular hexagon)
theta = (0:6)*pi/3 + pi/6;
hx = R*cos(theta);
hy = R*sin(theta);

% Generate a cellular grid
xIndex = -3:3;
yIndex = -3:3;

figure('Color', 'w', 'Position', [150, 100, 850, 750]);
hold on;
axis equal;
grid on;
box on;

count = 0;
for m = xIndex
    for n = yIndex
        % Center coordinates of pointy-top hexagons
        xc = 1.5*R*m;
        yc = sqrt(3)*R*(n + 0.5*mod(m, 2));

        % Skip cells outside a circular display area
        if sqrt(xc^2 + yc^2) > 5.5*R
            continue;
        end

        count = count + 1;

        % Assign frequency group using a repeating pattern
        group = mod(m + 2*n, N) + 1;

        % Draw hexagonal cell
        patch(xc + hx, yc + hy, 'w', ...
              'EdgeColor', 'k', 'LineWidth', 1.2);

        % Label the frequency group
        text(xc, yc, sprintf('F%d', group), ...
            'HorizontalAlignment', 'center', ...
            'FontWeight', 'bold', 'FontSize', 10);
    end
end

% Display reuse information
Q = sqrt(3*N);
D = Q*R;

title(sprintf('Frequency Reuse Pattern: N = %d, D/R = %.2f', N, Q), ...
      'FontSize', 12, 'FontWeight', 'bold');
xlabel('Distance (normalized)');
ylabel('Distance (normalized)');

fprintf('===============================================\n');
fprintf('CELLULAR FREQUENCY REUSE DEMONSTRATION\n');
fprintf('===============================================\n');
fprintf('Cluster size N                = %d\n', N);
fprintf('Normalized cell radius R      = %.2f\n', R);
fprintf('Reuse ratio D/R               = %.4f\n', Q);
fprintf('Normalized reuse distance D   = %.4f\n', D);
fprintf('Number of displayed cells     = %d\n', count);
fprintf('===============================================\n');
hold off;

clc;
clear;
close all;

% Obstacle categories
conditions = {'Clear LOS', 'Glass', 'Wooden Door', 'Human Body', 'Concrete Wall'};
avg_rssi = [-48.0, -53.2, -58.4, -62.6, -71.8]; % dBm
ref_rssi = avg_rssi(1);
add_path_loss = -(avg_rssi - ref_rssi);         % Relative loss in dB

figure('Color', 'w', 'Position', [150, 150, 900, 450]);

subplot(1, 2, 1);
bar(avg_rssi, 'FaceColor', [0.15, 0.45, 0.85]);
set(gca, 'XTickLabel', conditions, 'XTickLabelRotation', 25);
ylabel('Received RSSI (dBm)');
title('RSSI Across Obstacle Conditions');
grid on;

subplot(1, 2, 2);
bar(add_path_loss, 'FaceColor', [0.85, 0.25, 0.20]);
set(gca, 'XTickLabel', conditions, 'XTickLabelRotation', 25);
ylabel('Additional Path Loss (dB)');
title('Relative Attenuation vs. Obstacle');
grid on;

sgtitle('Indoor Path Loss Study (Fixed Distance = 5m)');

clc;
clear;
close all;
rng(1);

N = 1e5;
SNR_dB = 0:2:20;
A = 1;

% Generate random binary data
data = randi([0 1], 1, N);

% BPSK modulation
tx = A * (2*data - 1);

% Interference parameters
f_int = 0.07;
int_amp = 0.55;
n = 0:N-1;
interference = int_amp * sin(2*pi*f_int*n);

ber_noise = zeros(size(SNR_dB));
ber_interference = zeros(size(SNR_dB));

for k = 1:length(SNR_dB)

    snr_linear = 10^(SNR_dB(k)/10);
    sigma = sqrt(1/(2*snr_linear));
    noise = sigma * randn(1, N);

    % Noise only
    rx1 = tx + noise;
    detected1 = rx1 >= 0;
    ber_noise(k) = mean(detected1 ~= data);

    % Noise plus interference
    rx2 = tx + noise + interference;
    detected2 = rx2 >= 0;
    ber_interference(k) = mean(detected2 ~= data);

end

% Display results
T = table(SNR_dB', ber_noise', ber_interference', ...
    'VariableNames', ...
    {'SNR_dB', 'BER_Noise_Only', 'BER_Noise_Interference'});

disp(T);

% Plot BER
figure;
semilogy(SNR_dB, ber_noise, '-o', 'LineWidth', 1.5);
hold on;
semilogy(SNR_dB, ber_interference, '-s', 'LineWidth', 1.5);

grid on;
xlabel('SNR (dB)');
ylabel('Bit Error Rate (BER)');
title('Effect of Noise and Interference on Wireless Communication');
legend('AWGN only', 'AWGN + Interference', ...
    'Location', 'southwest');

clc;
clear;
close all;

% Sample measurements obtained from a smartphone
location = {'Classroom','Corridor','Near Window','Open Area', ...
            'Basement','Lift/Weak Area','Upper Floor','Entrance'};

networkType = {'4G/LTE','4G/LTE','5G','5G','3G','2G','4G/LTE','5G'};

% Signal strength in dBm
signalStrength = [-82 -76 -69 -61 -96 -101 -73 -66];

% Display data in a table
T = table(location', networkType', signalStrength', ...
    'VariableNames', {'Location','Network_Type','Signal_Strength_dBm'});

disp(T);

% Calculate average signal strength
avgSignal = mean(signalStrength);
fprintf('Average signal strength = %.2f dBm
', avgSignal);

% Bar graph
figure;
bar(signalStrength);
grid on;
xticks(1:length(location));
xticklabels(location);
xtickangle(35);
xlabel('Measurement Location');
ylabel('Signal Strength (dBm)');
title('Cellular Signal Strength at Different Locations');

% Line graph
figure;
plot(1:length(signalStrength), signalStrength, '-o', ...
    'LineWidth', 1.5, 'MarkerSize', 7);
grid on;
xticks(1:length(location));
xticklabels(location);
xtickangle(35);
xlabel('Measurement Location');
ylabel('Signal Strength (dBm)');
title('Variation of Cellular Signal Strength');
